import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 12 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * Practice Tests 1–11. Every math answer key has been solved and checked.
 */

// ─────────────────────── PRACTICE TEST 12 · R&W M1 (27) ──────────────────────
const T12_RW_M1: SatQuestion[] = [
  { id: "t12rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The glassblower's technique was so ______ that apprentices spent years simply learning to hold the rod at the correct angle.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["exacting", "casual", "playful", "trivial"], correct: 0, explanation: "The blank describes a technique so demanding that apprentices need years just to master holding the rod correctly, so it must mean rigorous and precise. \"Exacting\" means requiring great care, effort, and accuracy, which matches the long training and the \"correct angle\" detail exactly. \"Casual\" means relaxed and informal, the opposite of a skill needing years of practice. \"Playful\" means lighthearted, which does not fit a serious, difficult craft. \"Trivial\" means unimportant or easy, directly contradicting the years of effort the sentence stresses." },
  { id: "t12rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of advisers ______ scheduled to release its findings on Friday.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "Subject-verb agreement: the verb must agree with the true subject, not with a noun inside a prepositional phrase. The subject is the singular collective noun \"committee\"; \"of advisers\" is a prepositional phrase that cannot govern the verb. A singular subject takes the singular verb \"is,\" so A is correct. \"Are\" (B) and \"were\" (D) are plural and wrongly agree with the nearby plural \"advisers.\" \"Have been\" (C) is also plural and additionally shifts the tense away from the simple present the rest of the sentence uses." },
  { id: "t12rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Tardigrades, microscopic animals barely visible to the naked eye, can enter a dried-out state called cryptobiosis in which their metabolism nearly stops, letting them survive boiling heat, deep freezing, and even the vacuum of space.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["By nearly halting their metabolism, tardigrades can endure extreme conditions.", "Tardigrades are large animals that thrive only in mild climates.", "Tardigrades cannot survive any change in temperature.", "Tardigrades reproduce faster in the vacuum of space."], correct: 0, explanation: "The text's central claim is that by entering cryptobiosis, in which \"their metabolism nearly stops,\" tardigrades can \"survive boiling heat, deep freezing, and even the vacuum of space.\" Choice A captures exactly this link between the near-halt of metabolism and survival of extreme conditions. Choice B is wrong because the passage calls them \"microscopic animals barely visible to the naked eye,\" not large, and says they survive extremes, not only mild climates. Choice C contradicts the explicit list of temperature extremes they endure. Choice D introduces reproduction, a topic the passage never mentions, so it has no textual support." },
  { id: "t12rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The reservoir had dropped to record-low levels. ______, the city introduced strict limits on lawn watering.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "In contrast"], correct: 1, explanation: "The first sentence gives a cause (the reservoir hit record lows) and the second gives its effect (the city imposed watering limits), so the transition must signal cause-and-effect. \"Consequently\" means \"as a result,\" which fits perfectly. \"Nevertheless\" (A) and \"However\" (C) signal contrast or concession, but there is no opposition here, only a logical result. \"In contrast\" (D) sets up a difference between two things, but the two sentences agree rather than contrast, so it fails the logic." },
  { id: "t12rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit contained everything we needed ______ a tent, a stove, and a water filter.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needed, ", "needed: ", "needed; ", "needed "], correct: 1, explanation: "Rule: a colon introduces a list or explanation when a complete independent clause precedes it. \"The kit contained everything we needed\" is a complete sentence, and the items that follow specify \"everything,\" so the colon in B is correct. A comma (A) is too weak to introduce a formal list after a full clause. A semicolon (C) must join two independent clauses, but \"a tent, a stove, and a water filter\" is not an independent clause. No punctuation (D) runs the list directly into the clause without the needed separation." },
  { id: "t12rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her summary of the dense report was admirably ______, capturing the key findings in just two sentences.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["succinct", "rambling", "vague", "lengthy"], correct: 0, explanation: "The summary is praised (\"admirably\") for \"capturing the key findings in just two sentences,\" so the blank must mean brief yet complete. \"Succinct\" means expressed clearly in few words, matching both the brevity and the success. \"Rambling\" (B) means wandering and overlong, the opposite of two tight sentences. \"Vague\" (C) means unclear or imprecise, which contradicts \"capturing the key findings.\" \"Lengthy\" (D) means long, contradicting \"just two sentences.\"" },
  { id: "t12rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is awarded only to artists who have completed at least one full-length public exhibition and who live within the state; out-of-state applicants are not considered.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An artist living outside the state cannot receive the fellowship.", "Any artist may receive the fellowship regardless of residence.", "The fellowship funds artists who have never exhibited.", "The fellowship is limited to musicians."], correct: 0, explanation: "The text sets two conditions and adds that \"out-of-state applicants are not considered.\" That last clause directly supports A: an artist living outside the state cannot receive the fellowship. Choice B contradicts the residency rule, since residence clearly does matter. Choice C contradicts the requirement of \"at least one full-length public exhibition,\" so an artist who never exhibited cannot qualify. Choice D restricts the award to musicians, but the text refers only to \"artists\" and never limits it to musicians." },
  { id: "t12rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The team spent months gathering field samples. ______, it built a custom database to organize the results.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "Both sentences describe steps the team took, and building a database is an additional task on top of gathering samples, so an additive transition is needed. \"In addition\" signals one more action in a sequence, fitting the logic. \"However\" (A) signals contrast, but the two steps do not oppose each other. \"Otherwise\" (C) introduces a consequence of not doing something, which is not the relationship here. \"Instead\" (D) signals replacement, implying the database replaced the gathering, but the text presents both as completed steps." },
  { id: "t12rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the novel's plot ______, full of unexpected turns that kept them guessing until the final page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["suspenseful", "predictable", "dull", "tedious"], correct: 0, explanation: "The plot is \"full of unexpected turns that kept them guessing until the final page,\" so the blank must mean tense and gripping. \"Suspenseful\" means producing excited uncertainty about what happens next, exactly matching \"kept them guessing.\" \"Predictable\" (B) means easily foreseen, the direct opposite of \"unexpected turns.\" \"Dull\" (C) means boring, contradicting a plot that holds attention to the last page. \"Tedious\" (D) means tiresomely long or dull, again contradicting the engagement described." },
  { id: "t12rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Bees communicate the location of food through a precise \"waggle dance,\" in which the angle and duration of the movement encode the direction and distance to a flower patch.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees use a dance to convey where food can be found.", "Bees cannot share information with one another.", "Bees dance only for entertainment.", "Bees ignore the distance to food sources."], correct: 0, explanation: "The text says bees \"communicate the location of food\" through the waggle dance, whose \"angle and duration encode the direction and distance to a flower patch.\" Choice A restates this purpose of conveying where food is. Choice B contradicts the explicit fact that bees communicate. Choice C says the dance is only for entertainment, but the text states a clear informational purpose. Choice D claims bees ignore distance, yet the passage says duration encodes distance." },
  { id: "t12rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the manager nor the employees ______ aware of the schedule change until that morning.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "is", "were", "has been"], correct: 2, explanation: "Rule of proximity for \"neither...nor\": the verb agrees with the subject nearer to it. Here the nearer subject is the plural \"employees,\" so the verb must be plural. \"Were\" (C) is the correct plural past-tense form and matches the past-time context (\"until that morning\"). \"Was\" (A) and \"has been\" (D) are singular and would agree only with the farther subject \"manager.\" \"Is\" (B) is singular and also wrongly shifts to present tense, conflicting with the past-tense narration." },
  { id: "t12rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first prototype overheated within minutes. ______, the engineers gained crucial data that guided a far more reliable design.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "The prototype \"overheated within minutes\" (a setback), yet the engineers \"gained crucial data\" (a benefit), so the transition must signal contrast or concession. \"Still\" means \"nevertheless,\" capturing that something good came despite the failure. \"For instance\" (B) introduces an example, but the data is not an example of overheating. \"Therefore\" (C) signals a result, wrongly implying the failure caused the data in a straightforward way rather than despite it. \"In short\" (D) introduces a summary, but the second sentence adds new information rather than summarizing." },
  { id: "t12rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A regional study reported recycling rates of 41% in the north, 58% in the central zone, and 63% in the south.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The recycling rate was lowest in the north.", "The recycling rate was highest in the north.", "The central zone had the highest recycling rate.", "All three zones recycled at the same rate."], correct: 0, explanation: "The three reported rates are north 41%, central 58%, and south 63%. The smallest figure is 41% in the north, so A correctly identifies the north as lowest. Choice B reverses this; 41% is the lowest, not the highest. Choice C names the central zone (58%) as highest, but the south's 63% is higher. Choice D claims all three are equal, which the distinct percentages contradict." },
  { id: "t12rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive holds a manuscript ______ pages had survived a fire that destroyed most of the library.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["whose", "who's", "that", "which"], correct: 0, explanation: "The blank needs a possessive relative pronoun to show that the \"pages\" belong to the \"manuscript.\" \"Whose\" is the possessive relative pronoun and can refer to a thing as well as a person, so A is correct. \"Who's\" (B) is a contraction of \"who is\" and cannot show possession. \"That\" (C) and \"which\" (D) are relative pronouns that introduce clauses but cannot stand in for a possessive, so \"that pages had survived\" leaves no owner for the pages." },
  { id: "t12rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Rushing to catch the ferry, ______ the heavy suitcase slowed the traveler to a frustrating crawl.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["rushing to catch the ferry, the heavy suitcase slowed the traveler", "the traveler, rushing to catch the ferry, was slowed by the heavy suitcase", "the heavy suitcase, rushing to catch the ferry, slowed the traveler", "rushed, the suitcase slowed the traveler to the ferry"], correct: 1, explanation: "Rule: an introductory participial phrase must modify the noun that immediately follows it. \"Rushing to catch the ferry\" describes a person, so the traveler must come right after the comma. Only B does this: \"the traveler, rushing to catch the ferry, was slowed by the heavy suitcase.\" Choices A and C place \"the heavy suitcase\" right after the modifier, illogically saying the suitcase was rushing. Choice D's \"rushed, the suitcase\" again makes the suitcase the thing rushing and is also awkward and unclear." },
  { id: "t12rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers propose that brief afternoon naps improve memory because sleep helps the brain consolidate newly learned information.", prompt: "Which finding, if true, would most strengthen the researchers' claim?", type: "mcq", choices: ["Students who napped after studying recalled more material than those who stayed awake.", "Most people enjoy taking afternoon naps.", "Naps are more common in warm climates.", "People who nap tend to wake up groggy."], correct: 0, explanation: "Better recall among nappers than non-nappers directly supports the claim that naps aid memory consolidation, making choice A the strongest. Choice B concerns preference, choice C concerns climate, and choice D suggests a drawback, none of which support the memory claim." },
  { id: "t12rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with the lead actors, ______ attending the festival next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The subject is the singular \"director\"; the phrase \"together with the lead actors\" does not change the number, so the singular \"is\" is correct. The plural \"are,\" \"were,\" and \"have been\" wrongly agree with \"actors.\"" },
  { id: "t12rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to underscore that two independent labs reached the same surprising result. ______, both teams measured the reaction rate as identical to three decimal places.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "\"Remarkably\" emphasizes the striking agreement the researcher wants to underscore. \"By contrast\" and \"However\" signal opposition, and \"Otherwise\" introduces an alternative, none of which highlight the surprising match." },
  { id: "t12rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The essay's tone is deliberately ______: it never tells readers what to feel, instead laying out competing evidence and leaving the verdict to them.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["impartial", "biased", "sentimental", "hostile"], correct: 0, explanation: "Refusing to dictate feelings and presenting competing evidence describes an \"impartial\" tone. \"Biased\" and \"hostile\" imply taking a side, and \"sentimental\" implies emotional appeal, all of which contradict the neutral stance described." },
  { id: "t12rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate is offered only to drivers who purchased an electric vehicle after January 2024 and who registered it in the city.", prompt: "Which driver clearly qualifies for the rebate?", type: "mcq", choices: ["A driver who bought an electric vehicle in 2024 and registered it in the city.", "A driver who bought a gasoline vehicle in 2024 and registered it in the city.", "A driver who bought an electric vehicle in 2020 and registered it in the city.", "A driver who has never purchased a vehicle."], correct: 0, explanation: "Both conditions, a post-January-2024 electric purchase and city registration, are met only in choice A. Choice B fails the electric requirement, choice C fails the date requirement, and choice D fails both." },
  { id: "t12rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the dam ______ they reinforced the levees downstream.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["dam, and then", "dam and, then", "dam then", "dam, then"], correct: 0, explanation: "A comma plus the coordinating conjunction \"and\" correctly joins the two independent clauses. \"Dam, then\" creates a comma splice, \"dam then\" is a run-on, and \"dam and, then\" misplaces the comma after the conjunction." },
  { id: "t12rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although usually ______ in public, the scientist spoke with surprising warmth when describing her students' work.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["reserved", "outgoing", "boastful", "talkative"], correct: 0, explanation: "The contrast signaled by \"although\" with her \"surprising warmth\" implies her usual public manner was \"reserved\" (restrained). \"Outgoing,\" \"boastful,\" and \"talkative\" would not contrast with warmth and so break the intended opposition." },
  { id: "t12rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist observes that towns that built train stations in the 1800s tend to have larger downtowns today, crediting the early access to markets and labor.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Early rail access boosted markets and labor, producing larger downtowns.", "Train stations shrank the towns that built them.", "Downtown size is unrelated to rail history.", "Towns without stations grew the most."], correct: 0, explanation: "The economist credits early rail access to markets and labor for the larger downtowns, which choice A restates. Choice B reverses the effect, choice C denies the link the economist draws, and choice D contradicts the observation about stations." },
  { id: "t12rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The board delayed the vote ______ it still lacked the budget figures from two departments.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "No comma is needed before \"because\" when the dependent clause follows the main clause and is essential. A semicolon or colon would wrongly imply a stronger break, and \"because\" cannot begin an independent clause after a semicolon." },
  { id: "t12rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory switched to recycled materials. ______, it lowered its raw-material costs by nearly a third.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The cost reduction follows directly from switching to recycled materials, so the cause-effect transition \"As a result\" fits. \"Nevertheless\" and \"On the other hand\" signal contrast, and \"For example\" introduces an illustration rather than a consequence." },
  { id: "t12rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach offered ______ feedback, pointing to exactly which footwork each player should adjust.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "vague", "general", "confusing"], correct: 0, explanation: "Pointing to exactly which footwork to adjust describes \"specific\" feedback. \"Vague\" and \"general\" mean the opposite of precise, and \"confusing\" contradicts feedback a player can act on directly." },
  { id: "t12rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A long-term study found that removing an invasive grass from a marsh allowed native sedges to return, which in turn drew back the wading birds that had abandoned the wetland years earlier.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Removing the invasive grass set off a chain of recoveries that brought birds back.", "The invasive grass had no effect on the marsh.", "Wading birds drove the sedges out of the marsh.", "Native sedges declined after the grass was removed."], correct: 0, explanation: "Removing the grass let sedges return, which then drew the birds back, a chain of effects captured by choice A. Choice B contradicts the documented effect, choice C reverses the cause and effect, and choice D contradicts that sedges returned." },
];

// ─────────────────────── PRACTICE TEST 12 · R&W M2 easy (27) ─────────────────
const T12_RW_M2E: SatQuestion[] = [
  { id: "t12rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The lemonade was too ______, so she added a spoonful of sugar.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["sour", "sweet", "tall", "green"], correct: 0, explanation: "Adding sugar fixes a drink that is too \"sour,\" since sugar makes things sweeter. \"Sweet\" is the opposite problem, and \"tall\" and \"green\" do not describe taste." },
  { id: "t12rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Three puppies\" is plural, so the plural verb \"are\" is correct. \"Is,\" \"was,\" and \"am\" are singular and do not agree with the plural subject." },
  { id: "t12rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bats are not blind; many use sound echoes to find insects in the dark.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bats can locate food using sound, not just sight.", "Bats cannot find food at all.", "Bats only hunt during the day.", "Bats have no sense of hearing."], correct: 0, explanation: "The text says bats use sound echoes to find insects, which choice A states. Choice B contradicts that they find food, choice C contradicts hunting \"in the dark,\" and choice D contradicts their use of sound." },
  { id: "t12rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The movie was about to start. ______, we hurried to our seats.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "Hurrying is the result of the movie about to start, so \"So\" fits. \"However\" signals contrast, \"For example\" introduces an illustration, and \"Meanwhile\" signals a separate simultaneous event." },
  { id: "t12rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday they ______ a sandcastle on the beach.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["build", "builds", "built", "building"], correct: 2, explanation: "\"Yesterday\" signals the past, requiring the past-tense \"built.\" \"Build\" and \"builds\" are present tense, and \"building\" cannot stand alone as the main verb." },
  { id: "t12rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new sofa was so ______ that everyone wanted to sit on it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["comfortable", "broken", "wet", "loud"], correct: 0, explanation: "Everyone wanting to sit on it shows the sofa was \"comfortable.\" \"Broken,\" \"wet,\" and \"loud\" would discourage sitting, not invite it." },
  { id: "t12rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives good exercise, and reduces traffic.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is dangerous.", "Walking to school only saves money.", "Walking to school causes more traffic."], correct: 0, explanation: "Three benefits are listed, which choice A summarizes. Choice B adds danger not mentioned, choice C names only one of the three benefits, and choice D contradicts the claim that walking reduces traffic." },
  { id: "t12rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He ate ______ apple before the game.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the most", "some"], correct: 1, explanation: "\"Apple\" begins with a vowel sound, so \"an\" is correct. \"A\" is used before consonant sounds, and \"the most\" and \"some\" do not fit a single apple." },
  { id: "t12rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The directions were ______, so we reached the cabin without getting lost.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "wrong", "missing"], correct: 0, explanation: "Reaching the cabin without getting lost shows the directions were \"clear.\" \"Confusing,\" \"wrong,\" and \"missing\" would have caused getting lost, not prevented it." },
  { id: "t12rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My cousin and I ______ baking cookies this afternoon.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The compound subject \"my cousin and I\" is plural, so \"are\" is correct. \"Is,\" \"was,\" and \"am\" are singular and do not match the plural subject." },
  { id: "t12rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Trees give off oxygen, provide shade, and offer homes for birds.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Trees are useful in several ways.", "Trees are harmful to birds.", "Trees provide no shade.", "Trees give off no oxygen."], correct: 0, explanation: "Three useful roles are listed, which choice A summarizes. Choices B, C, and D each contradict one of the benefits the text states." },
  { id: "t12rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, we lit candles to see.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "Lighting candles is the result of the power going out, so \"As a result\" fits. \"However\" and \"Instead\" signal contrast, and \"For example\" introduces an illustration." },
  { id: "t12rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night the choir ______ a new song for the first time.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sing", "sings", "sang", "singing"], correct: 2, explanation: "\"Last night\" requires the past tense \"sang.\" \"Sing\" and \"sings\" are present tense, and \"singing\" cannot serve as the main verb alone." },
  { id: "t12rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After hiking all day, the campers were ______ and fell asleep quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "awake", "hungry", "excited"], correct: 0, explanation: "Falling asleep quickly after a long hike shows they were \"tired.\" \"Awake\" and \"excited\" would keep them up, and \"hungry\" does not explain falling asleep quickly." },
  { id: "t12rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from May to September but closes for the winter.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The pool is closed in January.", "The pool is open all year.", "The pool never opens.", "The pool closes in summer."], correct: 0, explanation: "January falls in the winter, when the pool is closed, supporting choice A. Choice B and C contradict the stated season, and choice D wrongly places the closure in summer." },
  { id: "t12rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after eating.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The singular possessive \"its\" matches the singular \"cat.\" \"It's\" means \"it is,\" and \"their\" and \"they're\" are plural and do not match." },
  { id: "t12rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals sleep through winter. ______, bears hibernate in their dens for months.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "Bears are an example of animals that sleep through winter, so \"For example\" fits. \"However\" and \"Instead\" signal contrast, and \"Otherwise\" introduces an alternative condition." },
  { id: "t12rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was so ______ that she could barely lift it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "soft", "quiet"], correct: 0, explanation: "Barely being able to lift it shows the backpack was \"heavy.\" \"Light\" is the opposite, and \"soft\" and \"quiet\" do not relate to lifting." },
  { id: "t12rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cups ______ drying on the rack by the sink.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Cups\" is plural, so the plural verb \"are\" is correct. \"Is,\" \"was,\" and \"am\" are singular and do not agree." },
  { id: "t12rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Salt was once so valuable that workers were sometimes paid with it.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Salt was highly valued in the past.", "Salt has always been worthless.", "Salt cannot be used as payment.", "Salt is harmful to workers."], correct: 0, explanation: "Being used to pay workers shows salt was highly valued, as choice A states. Choice B and C contradict that value and use, and choice D adds harm the text never mentions." },
  { id: "t12rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to picnic outside. ______, it began to rain.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The rain blocks the picnic plan, a contrast signaled by \"However.\" \"Therefore\" and \"Similarly\" suggest agreement or result, and \"For example\" introduces an illustration." },
  { id: "t12rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month the club ______ to host a fundraiser.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The singular \"club\" takes the singular \"plans,\" and the present tense fits \"next month\" as a planned future. \"Plan\" is plural, \"planned\" is past, and \"planning\" cannot stand alone." },
  { id: "t12rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The river was very ______ after the heavy rain, rushing past the banks.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["fast", "slow", "dry", "empty"], correct: 0, explanation: "Rushing past the banks shows the river was \"fast.\" \"Slow,\" \"dry,\" and \"empty\" all contradict water rushing after heavy rain." },
  { id: "t12rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Brushing your teeth removes food, prevents cavities, and keeps breath fresh.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Brushing teeth has several benefits.", "Brushing teeth causes cavities.", "Brushing teeth only removes food.", "Brushing teeth harms the gums."], correct: 0, explanation: "Three benefits are listed, summarized by choice A. Choices B, C, and D each contradict or narrow the benefits stated." },
  { id: "t12rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She wore ______ orange scarf to the parade.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the most", "some"], correct: 1, explanation: "\"Orange\" begins with a vowel sound, so \"an\" is correct. \"A\" precedes consonant sounds, and \"the most\" and \"some\" do not fit a single scarf." },
  { id: "t12rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The cake was easy to make. ______, it tasted delicious.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "A second good point is added, so \"In addition\" fits. \"However\" and \"Instead\" signal contrast, and \"Otherwise\" introduces an alternative condition." },
  { id: "t12rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "asleep", "angry"], correct: 0, explanation: "A surprising magic trick makes an audience \"amazed.\" \"Bored,\" \"asleep,\" and \"angry\" all contradict the wonder a vanishing rabbit produces." },
];

// ─────────────────────── PRACTICE TEST 12 · R&W M2 hard (27) ─────────────────
const T12_RW_M2H: SatQuestion[] = [
  { id: "t12rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The minister's statement was so ______ that supporters and critics alike claimed it endorsed their opposing positions.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "explicit", "blunt", "candid"], correct: 0, explanation: "A statement both sides can read as supporting them is \"ambiguous,\" open to multiple interpretations. \"Explicit,\" \"blunt,\" and \"candid\" all describe clear, direct language, which would not let opposing camps each claim it." },
  { id: "t12rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The chapter opens by tracing a single river's path from glacier to delta before widening, in its closing pages, into a general theory of how all great rivers shape civilizations.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from one detailed case to a broad generalization.", "It begins with a theory and offers no examples.", "It lists rivers without analysis.", "It repeats the same river description throughout."], correct: 0, explanation: "The text follows one river in detail and then generalizes to all rivers, a specific-to-general movement captured by choice A. Choice B reverses the order, choice C ignores the analytical generalization, and choice D contradicts the widening into a theory." },
  { id: "t12rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A solar panel produced 98% of its rated output in year 1, 96% in year 5, and 82% in year 20.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Output declined more sharply between years 5 and 20 than between years 1 and 5.", "Output rose as the panel aged.", "Output stayed exactly constant.", "The panel produced nothing by year 5."], correct: 0, explanation: "Output fell 2 points over the first 4 years but 14 points over the next 15 years, a steeper per-year drop, supporting choice A. Choice B reverses the trend, choice C ignores the decline, and choice D contradicts the 96% figure at year 5." },
  { id: "t12rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The new rail line would slash cross-town travel time. ______, it would require demolishing a historic market that has stood for two centuries.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "A clear benefit followed by a serious cost is a contrast, signaled by \"However.\" \"Therefore\" and \"Accordingly\" mark results, and \"Likewise\" marks similarity, none of which fit a benefit opposed by a drawback." },
  { id: "t12rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The program teaches students to analyze data, to write reports, and ______ findings to a live audience.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure with \"to analyze\" and \"to write\" requires the infinitive \"to present.\" The other forms break the parallel pattern of the series." },
  { id: "t12rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ its author's youth, presenting his reckless mistakes as frankly as his hard-won wisdom.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "narrate", "recall"], correct: 0, explanation: "Presenting mistakes frankly means the memoir refuses to \"romanticize\" (idealize) the author's youth. \"Condemn\" is the opposite extreme, and \"narrate\" and \"recall\" merely describe telling, not the slanting the sentence rejects." },
  { id: "t12rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats language change as decay from a pure original form, the newer model views it as a natural, ongoing process of adaptation.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older view of language change with a newer one.", "To prove language never changes.", "To summarize only the traditional account.", "To argue that language has no rules."], correct: 0, explanation: "The structure \"Where the traditional... the newer...\" sets two views of language change side by side, which choice A captures. Choice B contradicts that change occurs, choice C ignores the newer model, and choice D overstates the point." },
  { id: "t12rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The day shift cleared the backlog of orders by noon ______ the night shift was still sorting the same pile at dawn.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["noon, the", "noon; the", "noon the", "noon: the"], correct: 1, explanation: "Two independent clauses joined without a conjunction require a semicolon, so \"noon; the\" is correct. A comma alone creates a splice, no punctuation creates a run-on, and a colon wrongly signals that an explanation or list follows." },
  { id: "t12rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the lecture was packed with technical terms that even specialists had to pause and decode.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["accessible", "dense", "technical", "challenging"], correct: 0, explanation: "\"Far from\" signals the opposite of what follows; a lecture even specialists must decode is the opposite of \"accessible.\" \"Dense,\" \"technical,\" and \"challenging\" all match, not oppose, the difficulty described, so they fail the \"far from\" reversal." },
  { id: "t12rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Advocates insist the new fishing rules protected stocks without hurting local fleets. Yet in the rules' first season, the number of active boats fell by 12%.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It presents evidence that complicates the advocates' claim.", "It restates the advocates' claim exactly.", "It confirms that fleets were unaffected.", "It proposes an entirely new rule."], correct: 0, explanation: "A 12% drop in active boats complicates the claim that fleets were not hurt, making choice A correct. Choice B and C wrongly read the sentence as agreement, and choice D introduces a new proposal that is not present." },
  { id: "t12rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The proposal rested on three pillars ______ stable funding, trained staff, and community support.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["pillars,", "pillars:", "pillars;", "pillars"], correct: 1, explanation: "A colon correctly introduces the list that specifies the \"three pillars,\" since a complete clause precedes it. A comma is too weak, a semicolon must separate independent clauses, and no punctuation leaves the list dangling." },
  { id: "t12rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The algorithm sorted the familiar images flawlessly. ______, it stumbled badly on photographs taken in unusual lighting.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "A success followed by a notable failure is a concession, signaled by \"Nonetheless.\" \"Indeed\" and \"Likewise\" reinforce or compare, and \"Therefore\" marks a result, none of which fit the shift from success to failure." },
  { id: "t12rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, the new coating made the lenses 40% more scratch-resistant but also reduced their light transmission by 15%.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The coating improved scratch resistance but reduced light transmission.", "The coating improved both scratch resistance and light transmission.", "The coating had no measurable effect.", "Uncoated lenses were more scratch-resistant."], correct: 0, explanation: "The coating raised scratch resistance by 40% while lowering light transmission by 15%, a trade-off captured by choice A. Choice B ignores the loss, choice C ignores both effects, and choice D reverses the scratch-resistance result." },
  { id: "t12rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The sculpture that stands at the center of the plaza ______ from a single block of marble quarried nearby.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["come", "comes", "coming", "to come"], correct: 1, explanation: "The singular subject \"sculpture\" (not the plural \"plaza\" or anything in the modifier) takes the singular verb \"comes.\" \"Come\" is plural, and \"coming\" and \"to come\" cannot serve as the main verb." },
  { id: "t12rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor was prized for her ______ — for trimming every sentence to its leanest, most forceful form.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["economy", "verbosity", "hesitation", "carelessness"], correct: 0, explanation: "Trimming sentences to their leanest form describes \"economy\" of language. \"Verbosity\" is wordiness, the opposite, and \"hesitation\" and \"carelessness\" do not describe disciplined trimming." },
  { id: "t12rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author begins by admitting that early electric cars were slow and short-ranged, then argues that those very shortcomings forced the battery breakthroughs that made today's models practical.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an early weakness as the spur for later strengths.", "It denies that early electric cars had any flaws.", "It claims electric cars never improved.", "It lists car prices across the decades."], correct: 0, explanation: "The early shortcomings are reframed as the force driving later breakthroughs, which choice A states. Choice B contradicts the admitted flaws, choice C contradicts the improvement, and choice D introduces prices the text never discusses." },
  { id: "t12rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having rehearsed for months in a small studio ______ the cellist found the vast concert hall unexpectedly intimidating.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the vast concert hall felt intimidating", "the cellist found the vast concert hall intimidating", "intimidating was the vast concert hall", "it felt intimidating, the concert hall"], correct: 1, explanation: "The opening modifier must describe whoever rehearsed, the cellist, which only choice B places correctly after the modifier. The other choices attach the rehearsing to the hall or to \"it,\" creating a dangling modifier." },
  { id: "t12rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine cleared the virus rapidly in cell cultures. ______, its protection in living patients proved weaker and shorter-lasting.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In patients, however", "For this reason", "Similarly"], correct: 1, explanation: "The contrast between strong results in cultures and weaker results in patients is best signaled by \"In patients, however.\" \"Consequently\" and \"For this reason\" mark results, and \"Similarly\" marks agreement, none of which fit the contrast." },
  { id: "t12rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, noting how a four-note motif from the opening returns, disguised, in every movement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "fragmented", "aimless", "chaotic"], correct: 0, explanation: "A motif binding every movement together gives the symphony a \"cohesive\" design. \"Fragmented,\" \"aimless,\" and \"chaotic\" all imply a lack of unity, contradicting the recurring motif the critic praises." },
  { id: "t12rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across five schools, those that added a morning reading block saw test scores climb by an average of 14%, while those that kept their usual schedule saw essentially no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding a morning reading block was associated with higher scores.", "Keeping the usual schedule raised scores the most.", "Reading blocks had no relationship to scores.", "All five schools kept the same schedule."], correct: 0, explanation: "Schools that added the reading block gained 14% while others saw no change, supporting choice A. Choice B reverses the result, choice C denies the association, and choice D contradicts that some schools changed their schedule." },
  { id: "t12rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The inventor's early sketches — rough, smudged, and barely labeled ______ already hinted at the machine that would transform the industry.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sketches —", "sketches,", "sketches", "sketches;"], correct: 0, explanation: "A pair of dashes sets off the interrupting description, and the second dash must close what the first dash opened. A comma, no punctuation, or a semicolon would fail to match the opening dash." },
  { id: "t12rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The board dismissed the engineer's warning as ______, only to see the very failure she had predicted occur the following winter.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overcautious", "prophetic", "accurate", "justified"], correct: 0, explanation: "Dismissing a warning that later comes true means the board wrongly judged it \"overcautious.\" \"Prophetic,\" \"accurate,\" and \"justified\" would mean the warning was right, but the board dismissed it, so a dismissive word is needed." },
  { id: "t12rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One archaeologist argues the settlement was abandoned because of a prolonged drought; another insists the cause was conflict with neighboring groups. A third suggests the drought intensified the conflict, so the two causes worked together.", prompt: "Which choice best describes the third archaeologist's position?", type: "mcq", choices: ["Drought and conflict combined to cause the abandonment.", "Neither drought nor conflict played any role.", "Only drought mattered.", "The settlement was never abandoned."], correct: 0, explanation: "The third archaeologist says drought intensified conflict so both worked together, which choice A restates. Choice B denies both causes, choice C names only one, and choice D contradicts the abandonment all three discuss." },
  { id: "t12rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The crew rerouted the pipeline ______ the original path crossed an unstable fault line.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["pipeline, the", "pipeline; the", "pipeline the", "pipeline: the"], correct: 1, explanation: "Two independent clauses without a conjunction are correctly joined by a semicolon, so \"pipeline; the\" is right. A comma alone makes a splice, no punctuation makes a run-on, and a colon wrongly signals a list or explanation." },
  { id: "t12rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the reform's gains went mainly to large firms. ______, big corporations received generous tax breaks while small businesses got almost nothing.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The second sentence gives a specific illustration of the gains favoring large firms, so \"Specifically\" fits. \"In contrast\" and \"Nevertheless\" signal opposition, and \"Otherwise\" introduces an alternative, none of which match an example reinforcing the point." },
  { id: "t12rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying every thread together, the filmmaker leaves several subplots ______, trusting viewers to imagine their outcomes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "concluded", "obvious", "finished"], correct: 0, explanation: "Declining to tie threads together leaves the subplots \"unresolved.\" \"Concluded\" and \"finished\" mean the opposite, and \"obvious\" does not describe leaving outcomes to the imagination." },
  { id: "t12rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her data came from only one growing season, but she contends that the effect she measured was so strong and consistent that it warrants a multiyear study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She admits a limitation while defending the finding's importance.", "She claims her study had no weaknesses.", "She abandons her finding entirely.", "She argues that no further study is needed."], correct: 0, explanation: "She acknowledges the single-season limit yet defends the finding's strength and calls for more study, which choice A captures. Choice B denies the conceded limit, choice C contradicts her defense, and choice D contradicts her call for a multiyear study." },
];

// ─────────────────────── PRACTICE TEST 12 · MATH M1 (22) ─────────────────────
const T12_M_M1: SatQuestion[] = [
  { id: "t12m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve for x. Subtract 8 from both sides: 5x = 35. Divide by 5: x = 7. Check: 5(7) + 8 = 35 + 8 = 43, which matches the equation. A common trap is dividing 43 by 5 before subtracting the 8." },
  { id: "t12m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 2 cups of rice for every 5 servings. How many cups are needed for 15 servings?", type: "mcq", choices: ["6", "5", "7", "8"], correct: 0, explanation: "Goal: scale the ratio to 15 servings. The rice-per-serving rate is 2/5 = 0.4 cup. Multiply by 15 servings: 0.4 × 15 = 6 cups. Equivalently, 15 servings is 3 times 5 servings, so 2 × 3 = 6 cups. The trap is using 2 × 15 = 30 without dividing by 5." },
  { id: "t12m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 4, what is the value of f(2)?", type: "mcq", choices: ["8", "2", "20", "5"], correct: 0, explanation: "Goal: evaluate f at x = 2. Substitute: f(2) = 3(2²) − 4. Compute the square first: 2² = 4, so 3 × 4 = 12. Then 12 − 4 = 8. The trap is squaring after multiplying, giving (3·2)² − 4 = 32." },
  { id: "t12m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 18. What is its radius?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the radius from the diameter. The radius is half the diameter: r = 18 ÷ 2 = 9. Check: 2 × 9 = 18, the given diameter. The trap is doubling instead of halving." },
  { id: "t12m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 3x + 2 passes through the point (4, k). What is the value of k?", type: "grid", gridAnswers: ["14"], explanation: "Goal: find k, the y-value when x = 4. Substitute x = 4: k = 3(4) + 2. Multiply: 3 × 4 = 12. Add: 12 + 2 = 14. The trap is adding before multiplying, giving 3(6) = 18." },
  { id: "t12m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: find x given the mean is 9. The sum of three numbers equals 3 × 9 = 27. So 6 + 10 + x = 27, meaning 16 + x = 27, so x = 11. Check: (6 + 10 + 11)/3 = 27/3 = 9. The trap is forgetting to multiply the mean by 3." },
  { id: "t12m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x + 7 = 31, what is the value of x?", type: "mcq", choices: ["6", "9", "24", "7"], correct: 0, explanation: "Goal: solve for x. Subtract 7: 4x = 24. Divide by 4: x = 6. Check: 4(6) + 7 = 24 + 7 = 31. The trap is choosing 24, which is 4x rather than x." },
  { id: "t12m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: add the two roots. Factoring, x² − 9x + 20 = (x − 4)(x − 5), so the roots are 4 and 5. Their sum is 4 + 5 = 9. This also equals −b/a = −(−9)/1 = 9. The trap is reporting the product, 20, instead of the sum." },
  { id: "t12m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A book's price increased from $40 to $50. What was the percent increase?", type: "mcq", choices: ["25%", "20%", "10%", "125%"], correct: 0, explanation: "Goal: find the percent increase. The increase is 50 − 40 = 10. Divide by the original price: 10/40 = 0.25 = 25%. The trap is dividing by the new price (10/50 = 20%) instead of the original." },
  { id: "t12m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 85°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["50"], explanation: "Goal: find the third angle. The angles of a triangle sum to 180°. So the third angle is 180 − 45 − 85 = 50°. Check: 45 + 85 + 50 = 180. The trap is using 360° instead of 180°." },
  { id: "t12m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $30 per hour. Which equation gives the cost C for h hours?", type: "mcq", choices: ["C = 30h + 40", "C = 40h + 30", "C = 70h", "C = 30h − 40"], correct: 0, explanation: "Goal: model the cost. The flat fee $40 does not depend on hours, so it is the constant; the $30 per hour multiplies the hours h. This gives C = 30h + 40. The trap is swapping the rate and fee to get 40h + 30." },
  { id: "t12m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 3) = x² + bx − 15, what is the value of b?", type: "grid", gridAnswers: ["2"], explanation: "Goal: find b after expanding. Multiply (x + 5)(x − 3) = x² − 3x + 5x − 15 = x² + 2x − 15. Matching x² + bx − 15 gives b = 2. The trap is adding 5 and 3 to get 8 instead of combining −3x and +5x." },
  { id: "t12m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 300 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["120", "40", "150", "75"], correct: 0, explanation: "Goal: find 40% of 300. Convert: 40% = 0.40. Multiply: 0.40 × 300 = 120. Check: 120 is just under half of 300, consistent with 40%. The trap is reading 40 as the count instead of a percentage." },
  { id: "t12m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 1) = 3x + 7, what is the value of x?", type: "mcq", choices: ["6", "4", "3", "8"], correct: 0, explanation: "Goal: solve for x. Distribute: 5x − 5 = 3x + 7. Subtract 3x: 2x − 5 = 7. Add 5: 2x = 12. Divide: x = 6. Check: 5(6 − 1) = 25 and 3(6) + 7 = 25. The trap is forgetting to distribute the 5 to the −1." },
  { id: "t12m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(length + width) = 2(12 + 5) = 2(17) = 34. The trap is computing the area (12 × 5 = 60) instead of the perimeter." },
  { id: "t12m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve the exponential equation. Write 27 as a power of 3: 27 = 3³. So 3^(x−1) = 3³ means x − 1 = 3, giving x = 4. Check: 3^(4−1) = 3³ = 27. The trap is solving x − 1 = 27 and getting 28." },
  { id: "t12m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "180", "35"], correct: 0, explanation: "Goal: convert map inches to miles. Each inch represents 30 miles, so 5 inches represent 5 × 30 = 150 miles. The trap is adding (30 + 5 = 35) instead of multiplying." },
  { id: "t12m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope. Use rise over run: (15 − 3)/(6 − 2) = 12/4 = 3. Check: from (2,3) moving right 4 and up 12 reaches (6,15). The trap is inverting to (6−2)/(15−3) = 1/3." },
  { id: "t12m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x − 5, what value of x makes f(x) = 23?", type: "mcq", choices: ["7", "6", "8", "5"], correct: 0, explanation: "Goal: solve 4x − 5 = 23. Add 5: 4x = 28. Divide by 4: x = 7. Check: 4(7) − 5 = 28 − 5 = 23. The trap is dividing 23 by 4 before adding the 5." },
  { id: "t12m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 8. What is its area, in terms of π?", type: "mcq", choices: ["64π", "16π", "8π", "32π"], correct: 0, explanation: "Goal: find the area. Use A = πr² = π(8²) = 64π. The trap is using the circumference formula 2πr = 16π, or squaring incorrectly." },
  { id: "t12m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x − y = 17 and y = 3, what is the value of x?", type: "mcq", choices: ["4", "3", "5", "7"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3: 5x − 3 = 17. Add 3: 5x = 20. Divide: x = 4. Check: 5(4) − 3 = 20 − 3 = 17. The trap is subtracting 3 instead of adding it when isolating 5x." },
  { id: "t12m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 30-hour week?", type: "grid", gridAnswers: ["660"], explanation: "Goal: find total weekly pay. Multiply the hourly rate by the hours: 22 × 30 = 660 dollars. Break it down: 22 × 3 = 66, then ×10 = 660. The trap is adding 22 + 30 = 52 instead of multiplying." },
];

