// ─────────────────────── PRACTICE TEST 12 · MATH M2 hard (22) ────────────────
const T12_M_M2H: SatQuestion[] = [
  { id: "t12m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for the positive root. Add 64: x² = 64. Take the square root: x = ±8. Since x > 0, x = 8. The trap is reporting −8 or forgetting the positive-root condition." },
  { id: "t12m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 2y = 22 and x − 2y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: solve for x by elimination. Add the equations: (4x + 2y) + (x − 2y) = 22 + 3, so 5x = 25 and x = 5. Check: with x = 5, the first equation gives 2y = 22 − 20 = 2, so y = 1, and 5 − 2(1) = 3 holds. The trap is subtracting the equations, which keeps the y terms." },
  { id: "t12m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve the exponential equation. Express 64 as a power of 2: 64 = 2⁶. So x = 6. Check: 2⁶ = 64. The trap is dividing 64 by 2 to get 32 instead of finding the exponent." },
  { id: "t12m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $90 is marked up by 20%. What is the new price?", type: "mcq", choices: ["$108", "$110", "$72", "$112"], correct: 0, explanation: "Goal: apply a 20% markup. The increase is 20% of 90 = 0.20 × 90 = 18. Add to the original: 90 + 18 = 108. Equivalently, 1.20 × 90 = 108. The trap is subtracting 18 (a discount) to get 72." },
  { id: "t12m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 8 and 15. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find the hypotenuse with the Pythagorean theorem. c² = 8² + 15² = 64 + 225 = 289. Then c = √289 = 17. Check: 8-15-17 is a known Pythagorean triple. The trap is adding the legs (8 + 15 = 23) instead of using squares." },
  { id: "t12m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(4))?", type: "mcq", choices: ["28", "10", "34", "12"], correct: 0, explanation: "Goal: compose the function. First p(4) = 3(4) − 2 = 12 − 2 = 10. Then p(10) = 3(10) − 2 = 30 − 2 = 28. The trap is stopping at p(4) = 10 instead of applying p a second time." },
  { id: "t12m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 5y = 19 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["2.428571428571429", "17/7"], explanation: "Goal: solve the system by substitution. Replace x with y + 1: 2(y + 1) + 5y = 19, so 2y + 2 + 5y = 19, giving 7y + 2 = 19. Then 7y = 17 and y = 17/7. Check: 17/7 ≈ 2.43, and x = 17/7 + 1 = 24/7, with 2(24/7) + 5(17/7) = (48 + 85)/7 = 133/7 = 19. The trap is dropping the 2 when distributing." },
  { id: "t12m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 12 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the vertex x-coordinate. Use h = −b/(2a) with a = 1 and b = −8: h = −(−8)/(2·1) = 8/2 = 4. Check: this is the axis of symmetry, midway between the roots of (x−2)(x−6). The trap is forgetting the sign and getting −4." },
  { id: "t12m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 8/17. What is sin θ?", type: "mcq", choices: ["15/17", "8/15", "17/15", "17/8"], correct: 0, explanation: "Goal: find sin θ from cos θ. In a right triangle, adjacent = 8 and hypotenuse = 17, so the opposite side = √(17² − 8²) = √(289 − 64) = √225 = 15. Thus sin θ = opposite/hypotenuse = 15/17. This is the 8-15-17 triple. The trap is using 8/15, which is the tangent's reciprocal setup." },
  { id: "t12m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find b for a perfect square. A perfect square (x + a)² = x² + 2ax + a². Here a² = 25, so a = 5 (positive), and the middle term is 2a = 10, so b = 10. Check: (x + 5)² = x² + 10x + 25. The trap is taking b = 5 instead of 2·5." },
  { id: "t12m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope 3 and passes through (2, 1). What is its y-intercept?", type: "mcq", choices: ["−5", "5", "7", "−2"], correct: 0, explanation: "Goal: find b in y = 3x + b. Substitute the point (2, 1): 1 = 3(2) + b, so 1 = 6 + b and b = −5. Check: y = 3x − 5 gives y = 1 when x = 2. The trap is solving 1 = 6 + b as b = 5 by ignoring the sign." },
  { id: "t12m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $360. What was the original price?", type: "mcq", choices: ["$480", "$450", "$432", "$540"], correct: 0, explanation: "Goal: reverse a 25% discount. Paying after 25% off means paying 75% of the original: 0.75 × original = 360. Divide: original = 360 ÷ 0.75 = 480. Check: 25% of 480 is 120, and 480 − 120 = 360. The trap is adding 25% of 360 back, which undercounts." },
  { id: "t12m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 49 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-7"], explanation: "Goal: find the negative input. a² = 49 means a = ±7, and since a < 0, a = −7. Check: (−7)² = 49. The trap is giving 7 and ignoring the a < 0 condition." },
  { id: "t12m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find the cylinder's volume. Use V = πr²h = π(4²)(6) = π(16)(6) = 96π. The trap is using r instead of r², giving 24π, or squaring the height." },
  { id: "t12m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["1.3333333333333333", "4/3"], explanation: "Goal: solve for x. Subtract 1/4: 1/x = 1 − 1/4 = 3/4. Take the reciprocal of both sides: x = 4/3 ≈ 1.33. Check: 3/4 + 1/4 = 1. The trap is leaving the answer as 3/4 instead of taking the reciprocal." },
  { id: "t12m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "1"], correct: 0, explanation: "Goal: multiply the two roots. Factoring x² − 7x + 10 = (x − 2)(x − 5), the roots are 2 and 5, so the product is 2 × 5 = 10. This also equals c/a = 10/1. The trap is giving the sum, 7, instead of the product." },
  { id: "t12m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of red to blue tiles in a box is 2:7. If there are 54 tiles total, how many are blue?", type: "mcq", choices: ["42", "12", "21", "36"], correct: 0, explanation: "Goal: split 54 tiles in a 2:7 ratio. The total parts are 2 + 7 = 9, so each part is 54 ÷ 9 = 6 tiles. Blue gets 7 parts: 7 × 6 = 42. Check: red = 2 × 6 = 12, and 12 + 42 = 54. The trap is finding red instead of blue." },
  { id: "t12m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 5, what is the area of the larger?", type: "grid", gridAnswers: ["80"], explanation: "Goal: scale the area. Area scales by the square of the linear ratio, so the factor is 4² = 16. The larger area is 5 × 16 = 80. The trap is multiplying by 4 instead of 16." },
  { id: "t12m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: solve the radical equation. Square both sides: x + 5 = 36. Subtract 5: x = 31. Check: √(31 + 5) = √36 = 6. The trap is subtracting before squaring, or forgetting to square the 6." },
  { id: "t12m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 4y = 26 and y = 1, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "7"], correct: 0, explanation: "Goal: solve for x. Substitute y = 1: 5x − 4 = 26. Add 4: 5x = 30. Divide: x = 6. Check: 5(6) − 4(1) = 30 − 4 = 26. The trap is subtracting 4 instead of adding it when isolating 5x." },
  { id: "t12m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the root. Factor: x² − 6x + 9 = (x − 3)², which is 0 only when x − 3 = 0, so x = 3. Check: 3² − 6(3) + 9 = 9 − 18 + 9 = 0. The trap is reporting two distinct roots when this perfect square has a single repeated root." },
  { id: "t12m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of insects triples every day. If it starts at 20, how many are there after 3 days?", type: "mcq", choices: ["540", "180", "60", "1620"], correct: 0, explanation: "Goal: apply repeated tripling. After 3 days the population is 20 × 3³ = 20 × 27 = 540. Check by steps: day 1 → 60, day 2 → 180, day 3 → 540. The trap is multiplying by only 3 (giving 60) or by 9 instead of 27." },
];

